(async () => {
  const res = await fetch('/greenhouse_2026-05-22/anthropic/jobs/5023394008.html');
  const html = await res.text();
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const form = doc.querySelector('form');
  if (!form) return JSON.stringify({error: 'no form found in static HTML'});
  // Replace body with the form's outerHTML so cloak_snapshot sees real inputs.
  document.body.innerHTML = form.outerHTML;
  // Remove every script that React's hydration scaffold could reuse.
  document.querySelectorAll('script').forEach(s => s.remove());
  // Inspect what we got.
  const inputs = Array.from(document.querySelectorAll('input, select, textarea, button')).map(el => ({
    tag: el.tagName.toLowerCase(),
    type: el.getAttribute('type'),
    name: el.getAttribute('name'),
    id: el.id,
    placeholder: el.getAttribute('placeholder'),
    aria_label: el.getAttribute('aria-label'),
    label_text: (el.labels && el.labels[0]) ? el.labels[0].textContent.trim() : null,
    text: el.tagName.toLowerCase() === 'button' ? el.textContent.trim().slice(0,40) : null,
    accept: el.getAttribute('accept')
  }));
  const formAction = document.querySelector('form')?.getAttribute('action');
  return JSON.stringify({
    form_action: formAction,
    field_count: inputs.length,
    fields: inputs
  }, null, 2);
})();

