(() => {
  const b64 = "";
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const file = new File([bytes], 'mock_resume.pdf', { type: 'application/pdf' });
  const input = document.getElementById('resume');
  if (!input) return JSON.stringify({error: 'no #resume input'});
  const dt = new DataTransfer();
  dt.items.add(file);
  input.files = dt.files;
  input.dispatchEvent(new Event('change', { bubbles: true }));
  input.dispatchEvent(new Event('input', { bubbles: true }));
  return JSON.stringify({
    set_files_count: input.files.length,
    file_name: input.files[0]?.name,
    file_size: input.files[0]?.size,
    file_type: input.files[0]?.type,
    input_accept: input.getAttribute('accept')
  }, null, 2);
})();

