input.expression:
(() => {
  // With scripts removed in S4, the React Select listeners are gone — the combobox
  // input still accepts text but doesn't expand a flyout. We're not "selecting" via
  // the React Select state machine; we set the value imperatively to demonstrate
  // what an MCP-driven flow would do against a live (non-stripped) Greenhouse form.
  const country = document.getElementById('country');
  if (!country) return JSON.stringify({error: 'no country input'});
  // Simulate the type+Enter pattern that Greenhouse's React Select would accept:
  country.value = 'United States';
  country.dispatchEvent(new Event('input', { bubbles: true }));
  country.dispatchEvent(new Event('change', { bubbles: true }));
  // Also exercise a keyboard Enter to show the full sequence.
  country.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  return JSON.stringify({
    country_value_after: country.value,
    technique: 'imperative-value-set-then-Enter (would be type+Enter on live React Select)',
    note: 'fixture has no source/JoB-board field; this exercises the equivalent combobox'
  }, null, 2);
})();

